const LOGO_MOTTU_1 = "" + "" + "" + "" + "" + "";
const LOGO_MOTTU_2 = "" + "" + "";

// Aplicar logos aos elementos assim que o DOM carregar
document.addEventListener('DOMContentLoaded', () => {
    const headerLogo = document.getElementById('logoHeader');
    const footerLogo = document.getElementById('logoFooter');
    if (headerLogo) headerLogo.src = 'data:image/png;base64,' + LOGO_MOTTU_1;
    if (footerLogo) footerLogo.src = 'data:image/png;base64,' + LOGO_MOTTU_2;
});
